arguments.command:
cat > /tmp/joey-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s\n' "x-access-token" ;;
  *) printf '%s\n' "${GITHUB_TOKEN}" ;;
esac
EOF
chmod +x /tmp/joey-askpass.sh
cd /tmp/joey-wt && GIT_ASKPASS=/tmp/joey-askpass.sh GIT_TERMINAL_PROMPT=0 git -c credential.helper= push origin friend/joey 2>&1 | tail -4
